{
  "technical_and_design_decisions": [
    "For U1 (transactional context): In Node.js, pass the context as the first parameter to chaincode functions. In Java, create a new instance of the chaincode per transaction to ensure thread-safety.",
    "For U2/U3 (protos/utils move): Create a new package 'protoutils' and move all utilities, generated code, and extensions from protos/utils, updating all imports and build files accordingly.",
    "For U4 (Kafka health checks backport): Directly backport the existing master branch implementation to the 1.4 LTS branch, assuming the code is stable and compatible with the LTS API surface.",
    "For U5 (access control): Implement a dedicated read-only Invoke function that only allows GetState and similar read operations, and adjust permission checks to enforce access based on the actual operation type.",
    "For U6 (external endpoint): Introduce a new configuration option 'peer.externalEndpoint' that overrides the gossip external endpoint for service discovery, separate from the internal binding address.",
    "For U7 (version endpoint): Add a simple REST endpoint '/version' under the operations service that returns the peer/orderer version as a JSON object.",
    "For U8 (Go samples): Rewrite existing sample chaincode to follow Go idioms (proper error handling, naming conventions, use of standard library patterns)."
  ],
  "assumptions": [
    "All development is performed by a single developer working full-time on this increment.",
    "The developer has sufficient familiarity with the Hyperledger Fabric codebase and the specific modules affected.",
    "Testing includes unit tests and integration tests where applicable; no separate QA team is involved.",
    "Documentation updates are limited to inline comments and user-facing docs for each changed feature.",
    "The existing build system (Makefiles, CI) is used without changes.",
    "No external dependencies beyond the standard Hyperledger Fabric repository are required.",
    "The effort estimates are in work-hours and represent the most likely effort, not worst-case or best-case."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "U1 - Node.js context passing",
      "activity_description": "Modify the Node.js chaincode shim to automatically pass the transactional context as the first parameter to all chaincode functions. Update related tests and documentation.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Java per-transaction instance",
      "activity_description": "Design and implement per-transaction instantiation of Java chaincode objects to ensure thread-safety. Modify the Java shim and provide a new context interface. Update tests and documentation.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3",
      "activity_name": "U2/U3 - Move protos/utils to protoutils",
      "activity_description": "Create a new 'protoutils' package, move all files from protos/utils, update import paths across the codebase, adjust build scripts, and verify compilation. Write tests for the moved utilities.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "U4 - Backport Kafka health checks",
      "activity_description": "Analyze the master branch changes for Kafka health checks, apply them to the 1.4 LTS branch, resolve any merge conflicts, and run full Kafka integration tests.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A5",
      "activity_name": "U5 - Implement read-only Invoke",
      "activity_description": "Design and implement a new chaincode function (e.g., 'ReadOnlyInvoke') that only permits GetState and similar read operations. Modify the peer endorsement logic to accept this function without writer permission.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "U5 - Update access control checks",
      "activity_description": "Modify the chaincode invocation permission enforcement to inspect the actual operations (PutState vs GetState) and grant access accordingly. Update existing tests and add new ones.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "U6 - Add external endpoint config",
      "activity_description": "Add a new 'peer.externalEndpoint' configuration field, update gossip service to use it for external advertisement, and ensure it works with Docker networking. Write unit and integration tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8",
      "activity_name": "U7 - Version endpoint for operations service",
      "activity_description": "Add a '/version' REST endpoint to the operations service that returns the peer/orderer version. Implement handler, register route, add tests, and update documentation.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "U8 - Rewrite Go sample chaincode",
      "activity_description": "Review existing Go sample chaincodes, rewrite them to follow idiomatic Go patterns (e.g., proper error handling, naming, use of context), update tests, and ensure they compile and run correctly.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration and build verification",
      "activity_description": "Integrate all changes, run full build and CI pipelines, fix any cross-component issues, and verify end-to-end scenarios covering multiple stories.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation updates",
      "activity_description": "Update user-facing documentation for each changed feature, including release notes, API references, and configuration guides.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 164
  }
}

